 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [[bg] * w for _ in range(h)]

    # Each marker (6) is the middle cell of a vertical 4-0-4 pattern.
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 6:
                for dr, color in ((-1, 4), (0, 0), (1, 4)):
                    rr = r + dr
                    if 0 <= rr < h:
                        out[rr][c] = color

    # Keep any non-background, non-marker source cells (e.g. the seed pattern).
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != bg and value != 6:
                out[r][c] = value
    return out
